window.receiveProjectSource({"path": "src/microservices/entity_classification/services/helpers/external/accelerate_table_writes.py", "lines": ["\"\"\"External table write helpers for entity classification.\"\"\"", "", "import json", "import uuid", "from datetime import datetime", "from typing import Any, Dict, List, Optional, Set, Tuple", "from uuid import UUID", "", "from accelerate_models.accounts.app.models.corp_view.corporations import (", "    Corporation,", ")", "from accelerate_models.accounts.app.models.industry_view.industries import (", "    Industry as AccIndustry,", ")", "from accelerate_models.accounts.app.models.market_view.markets import (", "    Market as AccMarket,", ")", "from accelerate_models.ai.app.models.document_chunks import DocumentChunks", "from accelerate_models.common.models.enum import AccountType", "from accelerate_models.documents.app.models import (", "    DocContent,", "    DocEntityMap,", "    Document,", "    SourceData,", ")", "from accelerate_models.documents.app.models.enum import (", "    DocumentStatus,", "    DocumentType,", ")", "from sqlalchemy import select", "from sqlalchemy.dialects.postgresql import insert", "from sqlalchemy.ext.asyncio import AsyncSession", "", "from common.aws.s3_keys import build_s3_key_for_article_pdf", "from common.config import config as common_cfg", "from common.constants.source_data_models import (", "    LOC_DATA_MODEL_ID,", "    ORG_DATA_MODEL_ID,", "    PEOPLE_DATA_MODEL_ID,", ")", "from common.exceptions import (", "    DatabaseCommitException,", "    DatabaseFlushException,", "    DatabaseWriteException,", ")", "from common.exceptions.exceptions import DatabaseReadException", "from common.helpers import doc_images_projection as _doc_images_projection", "from common.helpers.get_article_title import get_article_title", "from common.helpers.publication_date import PUBLICATION_DATE_FLOOR, as_utc", "from common.models.enums import ArticleType", "from common.observability.metrics import incr", "from microservices.entity_classification.config import config", "from microservices.entity_classification.logging import logger", "from microservices.entity_classification.models import (", "    ArticleIndustry,", "    DocArticleMap,", "    Location,", "    Organization,", "    Person,", ")", "from microservices.entity_classification.observability import metrics as ec_metrics", "from microservices.entity_classification.schemas import (", "    DocEntityReason,", "    MatchedLocation,", "    MatchedOrganizationObj,", "    MatchedPersonObj,", ")", "from microservices.entity_classification.schemas.doc_entity_reason import (", "    DocEntityReasonSource,", ")", "from microservices.web_extraction.models import ArticleChunk", "from microservices.web_extraction.models.articles import Article", "", "# Sources whose matched-entity confidence flows into a DocEntityReason.", "_CVW_CONF_SOURCES = frozenset({DocEntityReasonSource.PERSON, DocEntityReasonSource.ORGANIZATION})", "_MVW_CONF_SOURCES = frozenset({DocEntityReasonSource.LOCATION})", "", "", "async def lookup_existing_doc_id(", "    dl_db: AsyncSession,", "    article_id: UUID,", "    manual_upload_account_id: UUID | None = None,", ") -> int | None:", "    \"\"\"Check doc_article_map for an existing document mapping.", "", "    Returns the doc_id if found, None otherwise.", "    Zyte path: WHERE article_id = :id AND manual_upload_account_id IS NULL", "    Manual upload path: WHERE article_id = :id AND manual_upload_account_id = :mua_id", "", "    :param dl_db: Datalake database session.", "    :type dl_db: AsyncSession", "    :param article_id: Article UUID.", "    :type article_id: UUID", "    :param manual_upload_account_id: Optional manual upload account UUID.", "    :type manual_upload_account_id: UUID | None", "    :return: The doc_id if a mapping exists, None otherwise.", "    :rtype: int | None", "    \"\"\"", "    filters = [DocArticleMap.article_id == article_id]", "    if manual_upload_account_id is not None:", "        filters.append(DocArticleMap.manual_upload_account_id == manual_upload_account_id)", "    else:", "        filters.append(DocArticleMap.manual_upload_account_id.is_(None))", "", "    return await dl_db.scalar(", "        select(DocArticleMap.doc_id)", "        .where(*filters)", "        .order_by(DocArticleMap.created_at.desc())", "        .limit(1)", "    )", "", "", "async def lookup_orphaned_document(", "    acc_db: AsyncSession,", "    article_id: UUID,", ") -> int | None:", "    \"\"\"Fallback: check accelerate Document table by doc_info->>'article_id'.", "", "    Covers the edge case where document creation succeeded but", "    doc_article_map write failed on a previous attempt.", "", "    :param acc_db: Accelerate database session.", "    :type acc_db: AsyncSession", "    :param article_id: Article UUID to search for.", "    :type article_id: UUID", "    :return: The document id if found, None otherwise.", "    :rtype: int | None", "    \"\"\"", "    result = await acc_db.scalar(", "        select(Document.id)", "        .where(Document.doc_info[\"article_id\"].astext == str(article_id))", "        .limit(1)", "    )", "    if result is not None:", "        logger.info(", "            \"Recovered orphaned document from accelerate\",", "            article_id=article_id,", "            doc_id=result,", "        )", "    return result", "", "", "async def _get_article_created_at(dl_db: AsyncSession, article_id: UUID) -> datetime:", "    \"\"\"Return canonical article created_at for deterministic S3 key generation.\"\"\"", "    created_at = await dl_db.scalar(", "        select(Article.created_at).where(Article.id == article_id).limit(1)", "    )", "    if created_at is None:", "        raise DatabaseReadException(", "            f\"Failed to read Article.created_at for article {article_id!r}\",", "            article_id=article_id,", "        )", "    return created_at", "", "", "async def write_doc_images_from_article_images(", "    dl_db: AsyncSession,", "    acc_db: AsyncSession,", "    article_id: UUID,", "    doc_id: int,", "    article_type: ArticleType,", ") -> None:", "    \"\"\"Write MAIN/THUMBNAIL/SUPPLEMENTAL DocImage rows from article_images.", "", "    Thin EC wrapper over :func:`common.helpers.doc_images_projection.", "    write_doc_images_from_article_images`, which owns the projection core and is", "    shared with web_extraction layer three (same-account DUPLICATE manual", "    uploads). This wrapper exists so EC's five ``sync.py`` call sites keep their", "    signature and so the wait budget stays EC's own config value, read at call", "    time because tests monkeypatch it.", "", "    ``article_type`` is kept in the signature because callers already pass it as", "    part of the EC layer-one contract; the core never reads it.", "", "    :param dl_db: Datalake database session.", "    :type dl_db: AsyncSession", "    :param acc_db: Accelerate database session.", "    :type acc_db: AsyncSession", "    :param article_id: Article whose ``article_images`` rows are the source.", "    :type article_id: UUID", "    :param doc_id: Target accelerate document id.", "    :type doc_id: int", "    :param article_type: Article type carried by the EC layer-one contract; unused.", "    :type article_type: ArticleType", "    :return: None", "    :rtype: None", "    :raises DatabaseWriteException: If any ``doc_images`` write fails.", "    :raises DatabaseCommitException: If the final commit fails.", "    \"\"\"", "    await _doc_images_projection.write_doc_images_from_article_images(", "        dl_db,", "        acc_db,", "        article_id=article_id,", "        doc_id=doc_id,", "        timeout_seconds=config.IMAGE_WAIT_TIMEOUT_SECONDS,", "    )", "", "", "def _evidence_to_str(e: Any) -> str:", "    \"\"\"Convert the JSONB evidence on Person/Organization into the", "    flat string stored in data_obj.", "", "    :param e: Evidence payload from the DB.", "    :type e: Any", "    :return: Stringified evidence.", "    :rtype: str", "    \"\"\"", "    if e is None:", "        return \"\"", "    if isinstance(e, str):", "        return e", "", "    if isinstance(e, dict):", "        # common conventions: text / quote / evidence", "        for key in (\"text\", \"quote\", \"evidence\"):", "            v = e.get(key)", "            if isinstance(v, str) and v.strip():", "                return v.strip()", "", "    # fallback: JSON-dump the whole thing", "    return json.dumps(e, ensure_ascii=False)", "", "", "async def create_doccontent_and_document(", "    dl_db: AsyncSession,", "    acc_db: AsyncSession,", "    article_id: UUID,", "    article_text: str,", "    *,", "    release_date: str,", "    source_url: Optional[str] = None,", ") -> Document:", "    \"\"\"Create a DocContent + Document row in the accelerate DB and return the Document.", "", "    :param dl_db: Datalake database session (datalake_db).", "    :type dl_db: AsyncSession", "    :param acc_db: Accelerate database session (accelerate_db).", "    :type acc_db: AsyncSession", "    :param article_id: UUID of the article", "    :type article_id: UUID", "    :param article_text: Full text of the article", "    :type article_text: str", "    :param release_date: ISO 8601 publish date (with offset) to store in doc_info.", "        Required, so a document is never written without one.", "    :type release_date: str", "    :param source_url: Optional source URL of the article (Zyte ``article_url`` or", "        an LLM-extracted URL from manual-upload content) stored in doc_info.", "        Only included when non-None \u2014 callers should pass None to omit the key.", "    :type source_url: Optional[str]", "", "    :return: Created Document row", "    :rtype: Document", "    \"\"\"", "    title_hash = str(uuid.uuid4())", "    doc_hash = str(uuid.uuid4())", "", "    # 1). build & add doc.doc_content row", "    doc_content = DocContent(", "        title_hash=title_hash,", "        doc_hash=doc_hash,", "        doc_text=article_text,", "    )", "", "    try:", "        acc_db.add(doc_content)", "    except Exception as e:", "        raise DatabaseFlushException(", "            f\"Failed to flush doc_content row for article {article_id!r} (caused by >>> {e!r})\",", "            doc_hash=doc_hash,", "        ) from e", "", "    try:", "        await acc_db.flush()", "    except Exception as e:", "        raise DatabaseFlushException(", "            f\"Failed to flush doc_content row for article {article_id!r} (caused by >>> {e!r})\",", "            doc_hash=doc_hash,", "        ) from e", "", "    # 2). build & add doc.document row", "    article_created_at = await _get_article_created_at(dl_db, article_id)", "    s3_key = build_s3_key_for_article_pdf(article_id, article_created_at)", "    title: str = await get_article_title(dl_db, article_id)", "    doc_info = {", "        \"article_id\": str(article_id),", "        \"source\": config.DOC_INFO_SOURCE,", "        \"release_date\": release_date,  # must be ISO 8601 string", "    }", "    if source_url is not None:", "        doc_info[\"source_url\"] = source_url", "", "    document = Document(", "        doc_type=DocumentType.NEWS_FEED,", "        title=title,", "        s3_bucket=common_cfg.S3_BUCKET_DATALAKE,", "        s3_key=s3_key,", "        file_type=config.DOCUMENT_FILE_TYPE,", "        doc_info=doc_info,", "        doc_content_id=doc_content.id,", "        status=DocumentStatus.QUESTIONING,", "    )", "", "    try:", "        acc_db.add(document)", "    except Exception as e:", "        raise DatabaseWriteException(", "            f\"Failed to write document row for article {article_id!r} (caused by >>> {e!r})\",", "            doc_content_id=doc_content.id,", "            doc_type=DocumentType.NEWS_FEED,", "            s3_key=s3_key,", "        ) from e", "", "    try:", "        await acc_db.commit()", "    except Exception as e:", "        raise DatabaseCommitException(", "            f\"Failed to commit document row for article {article_id!r} (caused by >>> {e!r})\",", "            doc_content_id=doc_content.id,", "            doc_type=DocumentType.NEWS_FEED,", "            s3_key=s3_key,", "        ) from e", "", "    return document", "", "", "async def create_doccontent_for_existing_document(", "    acc_db: AsyncSession,", "    doc_id: int,", "    article_text: str,", "    article_id: Optional[UUID] = None,", "    doc_info_source: Optional[str] = None,", "    status: Optional[DocumentStatus] = None,", "    *,", "    release_date: str,", "    source_url: Optional[str] = None,", ") -> Document:", "    \"\"\"Create a doc_content row and attach it to an existing document.", "", "    Accelerate pre-creates the document and may already have set", "    ``doc_info['release_date']``. A valid existing value is accelerate-owned and kept;", "    an absent or invalid one is replaced by ``release_date``, clamped to the", "    document's ``created_on``.", "", "    :param acc_db: Accelerate database session (accelerate_db).", "    :type acc_db: AsyncSession", "    :param doc_id: Document id to attach content to.", "    :type doc_id: int", "    :param article_text: Article text to store as doc_content.", "    :type article_text: str", "    :param article_id: Optional article id to persist in document.doc_info.", "    :type article_id: Optional[UUID]", "    :param doc_info_source: Optional source name for document.doc_info.", "    :type doc_info_source: Optional[str]", "    :param status: Optional document status update.", "    :type status: Optional[DocumentStatus]", "    :param release_date: ISO 8601 publish date (with offset) DL2 resolved; written when", "        the document has no valid ``release_date`` of its own. Required.", "    :type release_date: str", "    :param source_url: Optional source URL (validated http/https) to store in", "        ``document.doc_info[\"source_url\"]``. Only merged when non-None.", "    :type source_url: Optional[str]", "    :return: Updated Document row.", "    :rtype: Document", "    \"\"\"", "    title_hash = str(uuid.uuid4())", "    doc_hash = str(uuid.uuid4())", "", "    doc_content = DocContent(", "        title_hash=title_hash,", "        doc_hash=doc_hash,", "        doc_text=article_text,", "    )", "", "    try:", "        acc_db.add(doc_content)", "    except Exception as e:", "        raise DatabaseWriteException(", "            f\"Failed to flush doc_content row for doc {doc_id!r} (caused by >>> {e!r})\"", "        ) from e", "", "    try:", "        await acc_db.flush()", "    except Exception as e:", "        raise DatabaseFlushException(", "            f\"Failed to flush doc_content row for doc {doc_id!r} (caused by >>> {e!r})\"", "        ) from e", "", "    document = await acc_db.get(Document, doc_id)", "    if document is None:", "        raise DatabaseReadException(f\"Document {doc_id!r} not found in accelerate DB\")", "", "    document.doc_content_id = doc_content.id", "    doc_info = dict(document.doc_info or {})", "    if article_id is not None:", "        doc_info[\"article_id\"] = str(article_id)", "    if doc_info_source is not None:", "        doc_info[\"source\"] = doc_info_source", "    created_on = as_utc(document.created_on)", "    if _is_valid_existing_release_date(doc_info.get(\"release_date\"), created_on=created_on):", "        release_date_action = ec_metrics.RELEASE_DATE_ACTION_PRESERVED", "    else:", "        release_date_action = ec_metrics.RELEASE_DATE_ACTION_WRITTEN", "        clamped = min(as_utc(datetime.fromisoformat(release_date)), created_on)", "        doc_info[\"release_date\"] = clamped.isoformat()  # must be ISO 8601 string", "    if source_url is not None:", "        doc_info[\"source_url\"] = source_url", "    document.doc_info = doc_info", "    if status is not None:", "        document.status = status", "", "    try:", "        await acc_db.commit()", "    except Exception as e:", "        raise DatabaseCommitException(", "            f\"Failed to commit doc_content update for doc {doc_id!r} (caused by >>> {e!r})\"", "        ) from e", "", "    incr(ec_metrics.METRIC_RELEASE_DATE_EXISTING_DOC, tags=[f\"action:{release_date_action}\"])", "    return document", "", "", "def _is_valid_existing_release_date(value: object, *, created_on: datetime) -> bool:", "    \"\"\"Report whether a pre-set ``doc_info['release_date']`` should be kept.", "", "    Kept only when it is a non-empty ISO 8601 string with a UTC offset and falls", "    between :data:`PUBLICATION_DATE_FLOOR` and the document's ``created_on``. A naive", "    or date-only value counts as invalid, since its instant is ambiguous.", "", "    :param value: The existing ``doc_info['release_date']`` value, if any.", "    :type value: object", "    :param created_on: The document's ``created_on``, labelled UTC.", "    :type created_on: datetime", "    :return: ``True`` when the existing value is valid and must be preserved.", "    :rtype: bool", "    \"\"\"", "    if not isinstance(value, str) or not value.strip():", "        return False", "    try:", "        parsed = datetime.fromisoformat(value)", "    except ValueError:", "        return False", "    if parsed.tzinfo is None:", "        return False", "    return PUBLICATION_DATE_FLOOR <= parsed <= created_on", "", "", "async def _filter_invalid_fk_reasons(", "    acc_db: AsyncSession,", "    doc_id: int,", "    reasons: List[DocEntityReason],", ") -> List[DocEntityReason]:", "    \"\"\"Remove reasons whose industry_id, market_id, or corp_id does not exist in", "    the accelerate DB, preventing FK-violation errors on insert.", "", "    CVW ``corp_id`` is validated against the corporation master", "    (``cvw.corporations``). A resolved corp_id that does not exist there (e.g. a", "    bad ``original_id`` value) is dropped with a specific warning rather than", "    written \u2014 the only protection AC3 provides against non-colliding bad values.", "", "    The corp_id check applies to **all** CVW reasons regardless of how the", "    corp_id was obtained \u2014 both the ``original_id`` provenance path and the", "    pre-existing ``entities_source_map`` path. This is intentional: any", "    corp_id reaching insert, from any source, must reference a real", "    corporation row to avoid orphaned FK references.", "", "    :param acc_db: Accelerate database session.", "    :type acc_db: AsyncSession", "    :param doc_id: Document ID (used for log context).", "    :type doc_id: int", "    :param reasons: Pre-filtered reason rows.", "    :type reasons: List[DocEntityReason]", "    :return: Reasons with valid FK references only.", "    :rtype: List[DocEntityReason]", "    \"\"\"", "    candidate_industry_ids = {r.industry_id for r in reasons if r.industry_id is not None}", "    candidate_market_ids = {r.market_id for r in reasons if r.market_id is not None}", "    candidate_corp_ids = {", "        r.corp_id for r in reasons if r.entity_type == AccountType.CVW and r.corp_id is not None", "    }", "", "    valid_industry_ids: Set[int] = set()", "    if candidate_industry_ids:", "        result = await acc_db.execute(", "            select(AccIndustry.id).where(AccIndustry.id.in_(candidate_industry_ids))", "        )", "        valid_industry_ids = {row[0] for row in result}", "", "    valid_market_ids: Set[int] = set()", "    if candidate_market_ids:", "        result = await acc_db.execute(", "            select(AccMarket.id).where(AccMarket.id.in_(candidate_market_ids))", "        )", "        valid_market_ids = {row[0] for row in result}", "", "    valid_corp_ids: Set[int] = set()", "    if candidate_corp_ids:", "        result = await acc_db.execute(", "            select(Corporation.id).where(Corporation.id.in_(candidate_corp_ids))", "        )", "        valid_corp_ids = {row[0] for row in result}", "", "    filtered: List[DocEntityReason] = []", "    for r in reasons:", "        if r.industry_id is not None and r.industry_id not in valid_industry_ids:", "            logger.warning(", "                \"Excluding doc_entity_map row: industry_id not found in accelerate DB\",", "                doc_id=doc_id,", "                industry_id=r.industry_id,", "                reason=r.reason,", "            )", "            continue", "        if r.market_id is not None and r.market_id not in valid_market_ids:", "            logger.warning(", "                \"Excluding doc_entity_map row: market_id not found in accelerate DB\",", "                doc_id=doc_id,", "                market_id=r.market_id,", "                reason=r.reason,", "            )", "            continue", "        if (", "            r.entity_type == AccountType.CVW", "            and r.corp_id is not None", "            and r.corp_id not in valid_corp_ids", "        ):", "            logger.warning(", "                \"Excluding doc_entity_map row: corp_id not found in accelerate DB\",", "                doc_id=doc_id,", "                corp_id=r.corp_id,", "                reason=r.reason,", "            )", "            continue", "        filtered.append(r)", "", "    return filtered", "", "", "async def write_doc_entity_map_entries(", "    acc_db: AsyncSession,", "    doc_id: int,", "    reasons: List[DocEntityReason],", ") -> None:", "    \"\"\"Insert rows into doc.doc_entity_map for the given document, avoiding duplicates.", "", "    Constraints:", "        - (entity_type = 'CORPVIEW' and corp_id is not null)", "        - OR (entity_type = 'MARKETVIEW' and market_id is not null)", "", "    :param acc_db: Accelerate database session (accelerate_db).", "    :type acc_db: AsyncSession", "    :param doc_id: ID of the document in accelerate DB", "    :type doc_id: int", "    :param reasons: List of DocEntityReason rows to insert", "    :type reasons: List[DocEntityReason]", "    \"\"\"", "    if not reasons:", "        return", "    # Filter invalid/duplicate reasons, then query existing rows by entity type", "    # to avoid extra inserts and keep the write path minimal.", "    valid_reasons: List[DocEntityReason] = []", "    seen_keys: Set[Tuple[AccountType, Optional[int], Optional[int], Optional[int]]] = set()", "    for r in reasons:", "        if r.entity_type == AccountType.CVW and r.corp_id is None:", "            continue", "        if r.entity_type == AccountType.MVW and r.market_id is None:", "            continue", "        if r.entity_type == AccountType.IVW and r.industry_id is None:", "            continue", "", "        key = (r.entity_type, r.corp_id, r.market_id, r.industry_id)", "        if key in seen_keys:", "            logger.info(", "                \"Skipping duplicate doc_entity_map reason in batch\",", "                doc_id=doc_id,", "                entity_type=r.entity_type,", "                corp_id=r.corp_id,", "                market_id=r.market_id,", "                industry_id=r.industry_id,", "                reason=r.reason,", "            )", "            continue", "        seen_keys.add(key)", "        valid_reasons.append(r)", "", "    if not valid_reasons:", "        return", "", "    # Pre-validate industry_id, market_id, and corp_id against the accelerate DB", "    # so we don't attempt inserts that will hit FK violations (common in non-prod", "    # where the accelerate DB may not have all master-DB IDs).", "    valid_reasons = await _filter_invalid_fk_reasons(acc_db, doc_id, valid_reasons)", "", "    if not valid_reasons:", "        return", "", "    # Upsert each valid reason using the appropriate unique index per entity type", "    for r in valid_reasons:", "        values: Dict[str, Any] = {", "            \"doc_id\": doc_id,", "            \"entity_type\": r.entity_type,", "            \"corp_id\": r.corp_id,", "            \"market_id\": r.market_id,", "            \"industry_id\": r.industry_id,", "            \"reason\": r.reason,", "            \"confidence\": r.confidence,", "        }", "", "        # Determine the correct unique constraint columns per entity type", "        if r.entity_type == AccountType.CVW:", "            index_elements = [\"doc_id\", \"entity_type\", \"corp_id\"]", "        elif r.entity_type == AccountType.MVW:", "            index_elements = [\"doc_id\", \"entity_type\", \"market_id\"]", "        elif r.entity_type == AccountType.IVW:", "            index_elements = [\"doc_id\", \"entity_type\", \"industry_id\"]", "        else:", "            # Future account types: need a unique index added to DocEntityMap", "            logger.warning(", "                \"No unique index for entity_type; falling back to plain insert\",", "                doc_id=doc_id,", "                entity_type=r.entity_type,", "            )", "            acc_db.add(DocEntityMap(**values))", "            continue", "", "        # Use a savepoint so that an IntegrityError (e.g. FK violation on", "        # industry_id) only rolls back this single row instead of the whole", "        # transaction. Without it, a full rollback corrupts the asyncpg", "        # session and every subsequent operation fails with MissingGreenlet.", "        try:", "            async with acc_db.begin_nested():", "                stmt = insert(DocEntityMap).values(values)", "                stmt = stmt.on_conflict_do_update(", "                    index_elements=index_elements,", "                    set_={", "                        \"reason\": stmt.excluded.reason,", "                        \"confidence\": stmt.excluded.confidence,", "                    },", "                )", "                await acc_db.execute(stmt)", "        except Exception as e:", "            logger.error(", "                \"Failed to upsert doc_entity_map row; skipping entry\",", "                doc_id=doc_id,", "                entity_type=r.entity_type,", "                corp_id=r.corp_id,", "                market_id=r.market_id,", "                industry_id=r.industry_id,", "                reason=r.reason,", "                _exc=e,", "            )", "", "    try:", "        await acc_db.commit()", "    except Exception as e:", "        raise DatabaseCommitException(", "            f\"Failed to commit doc_entity_map rows for doc_id {doc_id} (caused by >>> {e!r})\"", "        ) from e", "", "", "async def write_document_chunks(", "    dl_db: AsyncSession,", "    acc_db: AsyncSession,", "    article_id: UUID,", "    doc_id: int,", ") -> None:", "    \"\"\"Write the web_extraction.article_chunks to doc.document_chunks table", "    for articles with a valid match reason. This is idempotent via", "    ON CONFLICT DO NOTHING against the unique constraint.", "", "    :param dl_db: Datalake database session (datalake_db).", "    :type dl_db: AsyncSession", "    :param acc_db: Accelerate database session (accelerate_db).", "    :type acc_db: AsyncSession", "    :param article_id: UUID of the article", "    :type article_id: UUID", "    :param doc_id: ID of the document in accelerate DB", "    :type doc_id: int", "    \"\"\"", "    # 1). get article chunks", "    chunks_sql = await dl_db.execute(", "        select(ArticleChunk)", "        .where(ArticleChunk.article_id == article_id)", "        .order_by(ArticleChunk.chunk_index)", "    )", "    article_chunks: List[ArticleChunk] = chunks_sql.scalars().all()", "", "    # 2). build doc chunks", "    doc_chunks: List[dict] = []", "    for ac in article_chunks:", "        doc_chunks.append(", "            {", "                \"document_id\": doc_id,", "                \"cloud_asset_content_id\": None,", "                \"embedding_model_id\": config.DEFAULT_EMBEDDING_MODEL_ID,", "                \"chunk_index\": ac.chunk_index,", "                \"chunk_text\": ac.chunk_text,", "                \"embedding\": ac.embedding,", "                \"context\": None,", "            }", "        )", "    if not doc_chunks:", "        return", "", "    # 3). bulk upsert chunks (refreshes stale data on reprocess)", "    try:", "        stmt = insert(DocumentChunks).values(doc_chunks)", "        stmt = stmt.on_conflict_do_update(", "            constraint=\"content_chunk_index_key\",", "            set_={", "                \"chunk_text\": stmt.excluded.chunk_text,", "                \"embedding\": stmt.excluded.embedding,", "                \"context\": stmt.excluded.context,", "            },", "        )", "        await acc_db.execute(stmt)", "    except Exception as e:", "        raise DatabaseWriteException(", "            f\"Failed to write document chunks for doc_id {doc_id} \"", "            f\"(article_id: {article_id}); caused by >>> {e!r}\",", "        ) from e", "", "    try:", "        await acc_db.commit()", "    except Exception as e:", "        raise DatabaseCommitException(", "            f\"Failed to commit document chunks for doc_id {doc_id} (article_id: {article_id}) \"", "            f\"(caused by >>> {e!r})\"", "        ) from e", "", "", "async def write_entity_source_data(", "    dl_db: AsyncSession,", "    acc_db: AsyncSession,", "    article_id: UUID,", "    doc_id: int,", "    activity_id: UUID | None = None,", ") -> None:", "    \"\"\"For a given article + document:", "      - Fetch ALL orgs/locations/people from entity_classification.*", "      - Build JSON payloads in the shapes used by doc.source_data", "      - Add SourceData rows for data_model_ids <11, 12, 13>", "", "    :param dl_db: Datalake database session (datalake_db).", "    :type dl_db: AsyncSession", "    :param acc_db: Accelerate database session (accelerate_db).", "    :type acc_db: AsyncSession", "    :param article_id: Article id to source entities from.", "    :type article_id: UUID", "    :param doc_id: Document id to attach source data to.", "    :type doc_id: int", "    :param activity_id: Optional EC layer-one activity UUID to scope entity reads.", "    :type activity_id: UUID | None", "    :return: None", "    :rtype: None", "    \"\"\"", "", "    # Helper to build entity filters scoped to the current activity", "    def _entity_filters(model: type[Any]) -> list[Any]:", "        filters = [model.article_id == article_id]", "        if activity_id is not None:", "            filters.append(model.layer_one_activity_id == activity_id)", "        return filters", "", "    # 1). Fetch entities from entity_classification.* (scoped to latest activity)", "    # Output: ['org1', 'org2', ...]", "    org_result = await dl_db.execute(select(Organization).where(*_entity_filters(Organization)))", "    org_rows = org_result.scalars().all()", "", "    org_names: List[str] = []", "    for org in org_rows:", "        name = (org.name or \"\").strip()", "        if name:", "            org_names.append(name)", "", "    # 2). Fetch people from entity_classification.* (scoped to latest activity)", "    # Output: [{\"name\": ..., \"evidence\": ...}, ...]", "    ppl_result = await dl_db.execute(select(Person).where(*_entity_filters(Person)))", "    people_rows = ppl_result.scalars().all()", "", "    people_objs: List[dict] = []", "    for p in people_rows:", "        parts = [", "            (p.first_name or \"\").strip(),", "            (p.middle_initial or \"\").strip(),", "            (p.last_name or \"\").strip(),", "        ]", "        full_name = \" \".join(x for x in parts if x).strip()", "        if not full_name:", "            continue", "", "        people_objs.append(", "            {", "                \"name\": full_name,", "                \"evidence\": _evidence_to_str(p.evidence),", "            }", "        )", "", "    # 3). Fetch locations from entity_classification.* (scoped to latest activity)", "    # Output: [{\"city\": ..., \"region\": ..., \"stateCode\": ...}, ...]", "    loc_result = await dl_db.execute(select(Location).where(*_entity_filters(Location)))", "    loc_rows = loc_result.scalars().all()", "", "    loc_objs: List[dict] = []", "    for loc in loc_rows:", "        loc_objs.append(", "            {", "                \"city\": loc.city,", "                \"region\": loc.region,", "                \"stateCode\": loc.state,", "            }", "        )", "", "    # 4). build source_data rows", "    rows_to_add: List[SourceData] = []", "", "    if org_names:", "        rows_to_add.append(", "            SourceData(", "                doc_id=doc_id,", "                data_model_id=ORG_DATA_MODEL_ID,", "                data_obj=org_names,", "            )", "        )", "", "    if loc_objs:", "        rows_to_add.append(", "            SourceData(", "                doc_id=doc_id,", "                data_model_id=LOC_DATA_MODEL_ID,", "                data_obj=loc_objs,", "            )", "        )", "", "    if people_objs:", "        rows_to_add.append(", "            SourceData(", "                doc_id=doc_id,", "                data_model_id=PEOPLE_DATA_MODEL_ID,", "                data_obj=people_objs,", "            )", "        )", "", "    if rows_to_add:", "        try:", "            # Deliberately not shared with the source_data projection core, whose", "            # loop has the same conflict target: change there applies here too.", "            for row in rows_to_add:", "                stmt = insert(SourceData).values(", "                    doc_id=row.doc_id,", "                    data_model_id=row.data_model_id,", "                    data_obj=row.data_obj,", "                )", "                stmt = stmt.on_conflict_do_update(", "                    index_elements=[\"doc_id\", \"data_model_id\"],", "                    set_={\"data_obj\": stmt.excluded.data_obj},", "                )", "                await acc_db.execute(stmt)", "        except Exception as e:", "            raise DatabaseWriteException(", "                f\"Failed to write source_data rows for doc_id {doc_id} (article_id: {article_id}) \"", "                f\"(caused by >>> {e!r})\",", "            ) from e", "", "    try:", "        await acc_db.commit()", "    except Exception as e:", "        raise DatabaseCommitException(", "            f\"Failed to commit source_data rows for doc_id {doc_id} (article_id: {article_id}) \"", "            f\"(caused by >>> {e!r})\",", "        ) from e", "", "", "def _is_subsidiary_source(source_table: str) -> bool:", "    \"\"\"Return True if the source table indicates a subsidiary match.", "", "    :param source_table: Source table name from entities_source_map.", "    :type source_table: str", "    :return: True if the source table contains 'subsidiaries'.", "    :rtype: bool", "    \"\"\"", "    return \"subsidiaries\" in source_table", "", "", "def build_doc_entity_reasons(", "    matched_people: List[MatchedPersonObj],", "    matched_orgs: List[MatchedOrganizationObj],", "    matched_locs: List[MatchedLocation],", "    matched_industries: List[ArticleIndustry],", "    matched_text_by_id: Dict[str, str],", "    pio_id_by_source_map_id: Optional[Dict[UUID, int]] = None,", "    source_table_by_source_map_id: Optional[Dict[UUID, str]] = None,", "    feed_market_ids: list[int] | None = None,", "    feed_description: str = \"\",", ") -> List[DocEntityReason]:", "    \"\"\"Flatten matched entities into DocEntityReason rows that will be used", "    to populate doc.doc_entity_map.", "", "    Rules:", "      - People/Orgs => corp-level (CVW), corp_id = pio_id, market_id = NULL", "      - Locations   => market-level (MVW), one reason per matched_market_ids entry, corp_id = NULL", "", "    :param matched_people: List of matched people objects", "    :type matched_people: List[MatchedPersonObj]", "    :param matched_orgs: List of matched organization objects", "    :type matched_orgs: List[MatchedOrganizationObj]", "    :param matched_locs: List of matched location objects", "    :type matched_locs: List[MatchedLocation]", "", "    :param matched_industries: Industries matched for this article", "    :type matched_industries: List[ArticleIndustry]", "    :param matched_text_by_id: Matched entity text keyed by matched_entities.id", "    :type matched_text_by_id: Dict[str, str]", "    :param pio_id_by_source_map_id: Map of matched_entities.entity_source_map_id to pio_id", "    :type pio_id_by_source_map_id: Optional[Dict[UUID, int]]", "    :param source_table_by_source_map_id: Map of entity_source_map_id to source_table name.", "        Used to determine Entity vs Subsidiary prefix for organization reasons.", "    :type source_table_by_source_map_id: Optional[Dict[UUID, str]]", "    :param feed_market_ids: Market IDs from the feed_markets configuration. Used to create", "        baseline MVW reasons; location-based reasons take priority for the same market_id.", "    :type feed_market_ids: list[int] | None", "    :param feed_description: Human-readable feed description included in feed-based reason text.", "    :type feed_description: str", "", "    :return: List of DocEntityReason rows", "    :rtype: List[DocEntityReason]", "    \"\"\"", "    # Fallback priority when category_priority is missing from a matched entity.", "    # Must be higher than any real nvw_match.categories.priority value so that", "    # unmatched entities lose to matched ones in lowest-wins filtering.", "    _DEFAULT_PRIORITY: float = 999.0", "", "    reasons: List[DocEntityReason] = []", "    seen: Set[Tuple[AccountType, Optional[int], Optional[int], Optional[int], str]] = set()", "", "    def add_reason(", "        entity_type: AccountType,", "        corp_id: Optional[int],", "        market_id: Optional[int],", "        industry_id: Optional[int],", "        reason_text: str,", "        source: DocEntityReasonSource,", "        priority: float = 0.0,", "    ) -> None:", "        \"\"\"Helper to add a reason if not already seen.", "        Uses a set to avoid duplicates.", "", "        :param entity_type: Account type for the reason.", "        :type entity_type: AccountType", "        :param corp_id: Corp id for CVW reasons.", "        :type corp_id: Optional[int]", "        :param market_id: Market id for MVW reasons.", "        :type market_id: Optional[int]", "        :param industry_id: Industry id for IVW reasons.", "        :type industry_id: Optional[int]", "        :param reason_text: Human-readable reason text.", "        :type reason_text: str", "        :param priority: Priority score for winner-take-all filtering.", "        :type priority: float", "        :return: None", "        :rtype: None", "        \"\"\"", "        key = (entity_type, corp_id, market_id, industry_id, reason_text)", "        if key in seen:", "            return", "        seen.add(key)", "        reasons.append(", "            DocEntityReason(", "                entity_type=entity_type,", "                corp_id=corp_id,", "                market_id=market_id,", "                industry_id=industry_id,", "                reason=reason_text,", "                priority=priority,", "                source=source,", "            )", "        )", "", "    # 1) People/Org CVW reasons require corp_id mapping (pio_id).", "    pio_id_by_source_map_id = pio_id_by_source_map_id or {}", "    source_table_by_source_map_id = source_table_by_source_map_id or {}", "    if matched_people:", "        for person in matched_people:", "            try:", "                entity_source_map_id = person.entity_source_map_id", "                # corp_id comes from the entities_source_map pio_id (when present)", "                # OR, for gap entities with no source-map row, the corp_id resolved", "                # from original_id at the matching layer.", "                corp_id = (", "                    pio_id_by_source_map_id.get(entity_source_map_id)", "                    if entity_source_map_id", "                    else None", "                )", "                if corp_id is None:", "                    corp_id = person.resolved_corp_id", "                if corp_id is None:", "                    logger.warning(", "                        \"Missing corp_id mapping for person\",", "                        entity_text=person.entity_text,", "                        entity_source_map_id=entity_source_map_id,", "                    )", "                    continue", "                is_owner = person.person_raw_data.is_owner", "                source_table = (", "                    source_table_by_source_map_id.get(entity_source_map_id, \"\")", "                    if entity_source_map_id", "                    else \"\"", "                ) or (person.resolved_source_table or \"\")", "                if is_owner and _is_subsidiary_source(source_table):", "                    prefix = \"Subsidiary CEO\"", "                elif is_owner:", "                    prefix = \"Entity CEO\"", "                else:", "                    prefix = \"Person\"", "                add_reason(", "                    entity_type=AccountType.CVW,", "                    corp_id=corp_id,", "                    market_id=None,", "                    industry_id=None,", "                    reason_text=f\"{prefix}: {person.entity_text}\",", "                    source=DocEntityReasonSource.PERSON,", "                    priority=person.person_raw_data.priority or _DEFAULT_PRIORITY,", "                )", "            except Exception as e:", "                logger.error(", "                    \"Skipping person due to error\",", "                    entity_text=getattr(person, \"entity_text\", None),", "                    _exc=e,", "                )", "", "    if matched_orgs:", "        for org in matched_orgs:", "            try:", "                entity_source_map_id = org.entity_source_map_id", "                # corp_id comes from the entities_source_map pio_id (when present)", "                # OR, for gap entities with no source-map row, the corp_id resolved", "                # from original_id at the matching layer.", "                corp_id = (", "                    pio_id_by_source_map_id.get(entity_source_map_id)", "                    if entity_source_map_id", "                    else None", "                )", "                if corp_id is None:", "                    corp_id = org.resolved_corp_id", "                if corp_id is None:", "                    logger.warning(", "                        \"Missing corp_id mapping for organization\",", "                        entity_text=org.entity_text,", "                        entity_source_map_id=entity_source_map_id,", "                    )", "                    continue", "                source_table = (", "                    source_table_by_source_map_id.get(entity_source_map_id, \"\")", "                    if entity_source_map_id", "                    else \"\"", "                ) or (org.resolved_source_table or \"\")", "                is_subsidiary = _is_subsidiary_source(source_table)", "                prefix = \"Subsidiary\" if is_subsidiary else \"Entity\"", "                add_reason(", "                    entity_type=AccountType.CVW,", "                    corp_id=corp_id,", "                    market_id=None,", "                    industry_id=None,", "                    reason_text=f\"{prefix}: {org.entity_text}\",", "                    source=DocEntityReasonSource.ORGANIZATION,", "                    priority=org.organization_raw_data.priority or _DEFAULT_PRIORITY,", "                )", "            except Exception as e:", "                logger.error(", "                    \"Skipping organization due to error\",", "                    entity_text=getattr(org, \"entity_text\", None),", "                    _exc=e,", "                )", "", "    # 2a) Location-based reasons (MVW, preferred over feed-based for same market).", "    #     One reason per matched market \u2014 a location nested in multiple markets emits a", "    #     row for each, keyed on its own market_id (dedup keys include market_id).", "    for loc in matched_locs:", "        try:", "            if not loc.matched_market_ids:", "                # (a). no match", "                continue", "", "            # (b). build match reason description", "            parts = []", "            if loc.city:", "                parts.append(loc.city)", "            if loc.region:", "                parts.append(loc.region)", "            if loc.state:", "                parts.append(loc.state.value if hasattr(loc.state, \"value\") else str(loc.state))", "", "            loc_desc = \", \".join(parts) if parts else \"Unknown location\"", "", "            # (c). emit one MVW reason per matched market (identical text, distinct market_id)", "            for market_id in loc.matched_market_ids:", "                add_reason(", "                    entity_type=AccountType.MVW,", "                    corp_id=None,", "                    market_id=market_id,", "                    industry_id=None,", "                    reason_text=f\"Location: {loc_desc}\",", "                    source=DocEntityReasonSource.LOCATION,", "                )", "        except Exception as e:", "            logger.error(", "                \"Skipping location due to error\",", "                matched_market_ids=getattr(loc, \"matched_market_ids\", None),", "                _exc=e,", "            )", "", "    # 2b) Feed-based market reasons (MVW, fallback when no location matched the same market)", "    for market_id in feed_market_ids or []:", "        add_reason(", "            entity_type=AccountType.MVW,", "            corp_id=None,", "            market_id=market_id,", "            industry_id=None,", "            reason_text=f\"Feed: {feed_description}\",", "            source=DocEntityReasonSource.FEED_MARKET,", "        )", "", "    # 3) Industry-based reasons (IVW, industry_id = industry_id)", "    for industry in matched_industries:", "        try:", "            matched_texts: List[str] = []", "            for matched_id in industry.matched_entity_ids or []:", "                key = str(matched_id)", "                text = matched_text_by_id.get(key)", "                if text:", "                    matched_texts.append(text)", "", "            unique_texts = sorted({t for t in matched_texts if t})", "            text_clause = \", \".join(unique_texts) if unique_texts else \"Unknown\"", "            reason_text = f\"Industry: {industry.industry_name} ({text_clause})\"", "", "            add_reason(", "                entity_type=AccountType.IVW,", "                corp_id=None,", "                market_id=None,", "                industry_id=industry.industry_id,", "                reason_text=reason_text,", "                source=DocEntityReasonSource.INDUSTRY,", "            )", "        except Exception as e:", "            logger.error(", "                \"Skipping industry due to error\",", "                industry_id=getattr(industry, \"industry_id\", None),", "                _exc=e,", "            )", "", "    # 4) Within-CVW priority: keep only the most specific reason per corp_id.", "    #    Uses category_priority from nvw_match.categories \u2014 lower value = more", "    #    specific match (Organization Name=20 beats Subsidiary=40 beats Sector=60).", "    cvw_best: Dict[int, DocEntityReason] = {}", "    for r in reasons:", "        if r.entity_type != AccountType.CVW or r.corp_id is None:", "            continue", "        existing = cvw_best.get(r.corp_id)", "        if existing is None or r.priority < existing.priority:", "            cvw_best[r.corp_id] = r", "", "    if cvw_best:", "        filtered: List[DocEntityReason] = []", "        for r in reasons:", "            if r.entity_type == AccountType.CVW and r.corp_id is not None:", "                if cvw_best.get(r.corp_id) is r:", "                    filtered.append(r)", "            else:", "                filtered.append(r)", "        reasons = filtered", "", "    return reasons", "", "", "def populate_doc_entity_reason_confidence(", "    reasons: List[DocEntityReason],", "    matched_people: List[MatchedPersonObj],", "    matched_orgs: List[MatchedOrganizationObj],", "    matched_locs: List[MatchedLocation],", "    pio_id_by_source_map_id: Optional[Dict[UUID, int]] = None,", ") -> None:", "    \"\"\"Populate ``confidence`` on each DocEntityReason in place (max-wins).", "", "    Keyed by ``corp_id`` (CVW, from matched people/orgs via", "    ``pio_id_by_source_map_id``) and ``market_id`` (MVW, from matched", "    locations). Industries and feed-market reasons have no source", "    confidence and keep ``DEFAULT_DOC_ENTITY_CONFIDENCE``. Keying by id", "    (not by surviving reason object) is robust to the CVW", "    priority-collapse in ``build_doc_entity_reasons``.", "", "    :param reasons: Reason rows to enrich in place.", "    :type reasons: List[DocEntityReason]", "    :param matched_people: Matched people with optional confidence on", "        ``person_raw_data.confidence``.", "    :type matched_people: List[MatchedPersonObj]", "    :param matched_orgs: Matched organizations with optional confidence", "        on ``organization_raw_data.confidence``.", "    :type matched_orgs: List[MatchedOrganizationObj]", "    :param matched_locs: Matched locations with optional ``confidence``.", "    :type matched_locs: List[MatchedLocation]", "    :param pio_id_by_source_map_id: Map from ``entity_source_map_id`` to", "        ``corp_id`` (pio_id). Required to resolve people/org confidence", "        to a CVW reason key.", "    :type pio_id_by_source_map_id: Optional[Dict[UUID, int]]", "    \"\"\"", "    pio_id_map = pio_id_by_source_map_id or {}", "", "    conf_by_corp: Dict[int, float] = {}", "    for person in matched_people:", "        esm_id = person.entity_source_map_id", "        # corp_id key: source-map pio_id first, resolved-from-original_id fallback", "        # second, so gap-entity CVW reasons inherit the matched person confidence.", "        corp_id = pio_id_map.get(esm_id) if esm_id else None", "        if corp_id is None:", "            corp_id = person.resolved_corp_id", "        if corp_id is None:", "            continue", "        raw_c = person.person_raw_data.confidence", "        c = raw_c if raw_c is not None else 0.0", "        if c > conf_by_corp.get(corp_id, 0.0):", "            conf_by_corp[corp_id] = c", "", "    for org in matched_orgs:", "        esm_id = org.entity_source_map_id", "        # corp_id key: source-map pio_id first, resolved-from-original_id fallback", "        # second, so gap-entity CVW reasons inherit the matched org confidence.", "        corp_id = pio_id_map.get(esm_id) if esm_id else None", "        if corp_id is None:", "            corp_id = org.resolved_corp_id", "        if corp_id is None:", "            continue", "        raw_c = org.organization_raw_data.confidence", "        c = raw_c if raw_c is not None else 0.0", "        if c > conf_by_corp.get(corp_id, 0.0):", "            conf_by_corp[corp_id] = c", "", "    conf_by_market: Dict[int, float] = {}", "    for loc in matched_locs:", "        raw_c = loc.confidence", "        c = raw_c if raw_c is not None else 0.0", "        # Fan the location confidence out to every matched market (max-wins per market).", "        for market_id in loc.matched_market_ids:", "            if c > conf_by_market.get(market_id, 0.0):", "                conf_by_market[market_id] = c", "", "    for r in reasons:", "        if (", "            r.entity_type == AccountType.CVW", "            and r.corp_id is not None", "            and r.source in _CVW_CONF_SOURCES", "        ):", "            if r.corp_id in conf_by_corp:", "                r.confidence = max(0.0, min(conf_by_corp[r.corp_id], 1.0))", "        elif (", "            r.entity_type == AccountType.MVW", "            and r.market_id is not None", "            and r.source in _MVW_CONF_SOURCES", "        ):", "            if r.market_id in conf_by_market:", "                r.confidence = max(0.0, min(conf_by_market[r.market_id], 1.0))", "        # IVW, feed-market, and unsourced reasons keep DEFAULT_DOC_ENTITY_CONFIDENCE."], "blocks": [{"start": 1, "end": 78, "label": "Imports and module setup"}, {"start": 79, "end": 112, "label": "def lookup_existing_doc_id"}, {"start": 113, "end": 142, "label": "def lookup_orphaned_document"}, {"start": 143, "end": 155, "label": "def _get_article_created_at"}, {"start": 156, "end": 198, "label": "def write_doc_images_from_article_images"}, {"start": 199, "end": 223, "label": "def _evidence_to_str"}, {"start": 224, "end": 325, "label": "def create_doccontent_and_document"}, {"start": 326, "end": 421, "label": "def create_doccontent_for_existing_document"}, {"start": 422, "end": 446, "label": "def _is_valid_existing_release_date"}, {"start": 447, "end": 536, "label": "def _filter_invalid_fk_reasons"}, {"start": 537, "end": 658, "label": "def write_doc_entity_map_entries"}, {"start": 659, "end": 729, "label": "def write_document_chunks"}, {"start": 730, "end": 871, "label": "def write_entity_source_data"}, {"start": 872, "end": 882, "label": "def _is_subsidiary_source"}, {"start": 883, "end": 1173, "label": "def build_doc_entity_reasons"}, {"start": 1174, "end": 1260, "label": "def populate_doc_entity_reason_confidence"}], "lineCount": 1260, "sha256": "8697434ecd75a5042a184452dfb3ad7d9a826ccc87b38807d4c2d510126b995b", "endsWithNewline": true});
